def read_json(path, *, budget=1.0, clock=time.monotonic, sleep=time.sleep,
              load=None, windows=None):
    if not 0 <= budget <= 2.0:
        raise ValueError('State-read retry budget must be 0..2 seconds')
    if windows is None:
        windows = os.name == 'nt'
    if load is None:
        load = lambda: Path(path).read_text(encoding='utf-8-sig')
    deadline = clock() + budget
    while True:
        try:
            return json.loads(load())
        except OSError as exc:
            transient = windows and (getattr(exc, 'winerror', None) in (5, 32, 33)
                                     or exc.errno == errno.EACCES)
            remaining = deadline - clock()
            if not transient or remaining <= 0:
                raise
            sleep(min(0.025, remaining))

def _safe(self, value, budget, depth=0):
    if depth >= 32 or budget[0] <= 0:
        return '[TRUNCATED]'
    budget[0] -= 1
    if isinstance(value, str):
        for secret in self.secrets:
            value = value.replace(secret, '[REDACTED]')
        kept = value[:budget[0]]
        budget[0] -= len(kept)
        return kept + ('[TRUNCATED]' if len(kept) < len(value) else '')
    if isinstance(value, dict):
        result = {}
        for key, child in value.items():
            if budget[0] <= 0:
                result['[TRUNCATED]'] = True
                break
            safe_key = self._safe(str(key), budget, depth + 1)
            normalized = ''.join(char for char in str(key).lower() if char.isalnum())
            result[safe_key] = ('[REDACTED]' if normalized in _CREDENTIAL_FIELDS
                                else self._safe(child, budget, depth + 1))
        return result
    if isinstance(value, (list, tuple)):
        result = []
        for child in value:
            if budget[0] <= 0:
                result.append('[TRUNCATED]')
                break
            result.append(self._safe(child, budget, depth + 1))
        return result
    return value

def admission_floors(context, checkpoint='w4b'):
    if type(context) is not int or not 4096 <= context <= 262144:
        raise ValueError('Context must be 4096..262144')
    if checkpoint not in ('w4b','v2'): raise ValueError('Unknown checkpoint')
    if checkpoint == 'v2':
        # Explicitly selected v2 startup admission; runtime reserve and
        # total-commit admission remain independently enforced.
        physical = 35
    else:
        physical = HOST_STARTUP_DECLINE_GIB + HOST_UNCERTAINTY_GIB + RUNTIME_RESERVE_GIB
    # Keep the existing conservative total-commit estimate until new runs
    # provide measured evidence for both checkpoints. Commit is not RAM.
    kv_commit_gib = (context - 4096) * 32768 / (1024 ** 3)
    commit = max(117, math.ceil(100.247 + 4 + RUNTIME_RESERVE_GIB + kv_commit_gib))
    return physical, commit

def validate(defaults):
    if type(defaults) is not dict:
        raise ValueError('API defaults must be a JSON object')
    result = {}
    for key, value in defaults.items():
        if key not in FIELDS:
            raise ValueError('Unsupported API default: ' + str(key))
        if key == 'enable_thinking' and type(value) is not bool:
            raise ValueError('enable_thinking must be a boolean')
        if key == 'reasoning_effort' and (type(value) is not str or value not in EFFORTS):
            raise ValueError('reasoning_effort must be minimal, low, medium, high, xhigh or max; use enable_thinking=false for Off')
        if key == 'max_thinking_tokens' and (type(value) is not int or not 1 <= value <= 1 << 30):
            raise ValueError('max_thinking_tokens must be an integer from 1 to 1073741824')
        result[key] = value
    return result

def replace_option(args, flag, value):
    count = args.count(flag)
    if count > 1 or (count and args.index(flag) + 1 >= len(args)):
        raise ValueError('Ambiguous native option: ' + flag)
    if count:
        args[args.index(flag) + 1] = str(value)
    else:
        args.extend([flag, str(value)])

def resolve_cgroup_memory_path(cgroup_text, mountinfo_text):
    memberships = []
    for line in cgroup_text.splitlines():
        fields = line.split(':', 2)
        if len(fields) != 3:
            raise ValueError('Malformed cgroup membership')
        if fields[:2] == ['0', '']:
            # /proc/self/cgroup is literal, unlike mountinfo path fields.
            if fields[2].endswith(' (deleted)'):
                raise ValueError('Deleted cgroup membership')
            memberships.append(_path_components(fields[2]))
    if len(memberships) != 1:
        raise ValueError('Exactly one unified cgroup membership required')
    member = memberships[0]
    candidates = []
    for line in mountinfo_text.splitlines():
        parts = line.split(' - ')
        if len(parts) != 2:
            raise ValueError('Malformed mountinfo record')
        fields, filesystem = parts[0].split(), parts[1].split()
        if len(fields) < 6 or len(filesystem) < 3:
            raise ValueError('Malformed mountinfo fields')
        if filesystem[0] != 'cgroup2':
            continue
        root = _path_components(_mount_path(fields[3]))
        mountpoint = _path_components(_mount_path(fields[4]))
        if member[:len(root)] == root:
            path = PurePosixPath('/').joinpath(*mountpoint, *member[len(root):])
            candidates.append((len(root), path))
    if not candidates:
        raise ValueError('No cgroup2 mount covers unified membership')
    specificity = max(depth for depth, path in candidates)
    matches = [path for depth, path in candidates if depth == specificity]
    if len(matches) != 1:
        raise ValueError('Ambiguous cgroup2 mount for unified membership')
    return matches[0]

def receipt_matches(receipt, identity, *, size=SIZE, sha=SHA, source=None):
    return (isinstance(identity,dict)
            and all(type(identity.get(key)) is int for key in ('size','device','inode','mtime_ns','ctime_ns'))
            and isinstance(receipt,dict) and receipt.get('sha256')==sha
            and receipt.get('identity')==identity and identity.get('size')==size
            and (source is None or receipt.get('source')==source))

def frame():
    m, p = Memory(), Performance()
    m.length, p.length = ctypes.sizeof(m), ctypes.sizeof(p)
    if not ctypes.windll.kernel32.GlobalMemoryStatusEx(ctypes.byref(m)):
        raise OSError('GlobalMemoryStatusEx_failed')
    if not ctypes.windll.psapi.GetPerformanceInfo(ctypes.byref(p), p.length):
        raise OSError('GetPerformanceInfo_failed')
    return dict(available_bytes=m.available, committed_bytes=p.commit_total*p.page_size,
                commit_limit_bytes=p.commit_limit*p.page_size,
                commit_headroom_bytes=(p.commit_limit-p.commit_total)*p.page_size)

